//! Visual-motion policy, provenance, and quality-harness extension.
//!
//! Motion remains a derived presentation concern. The module validates
//! versioned metadata and generated bytes, then contributes checks to the
//! existing `identity.quality-report/v1` decision. It does not publish assets,
//! capture browsers, or approve creative intent.

#[cfg(test)]
mod tests;

use std::collections::BTreeSet;

use serde::{Deserialize, Serialize};

