use crate::quality::{
    HumanReviewEvidence, QualityCategory, QualityCheck, QualityCoverage, QualityHarness,
    QualityInput, QualityReport, QualityStatus,
};

pub const MOTION_POLICY_SCHEMA: &str = "identity.motion-policy/v1";
pub const VISUAL_MOTION_MANIFEST_SCHEMA: &str = "identity.visual-motion-manifest/v1";

