#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct MotionPolicy {
    pub schema: String,
    pub durations_ms: MotionDurationBudgets,
    pub asset_bytes: MotionAssetBudgets,
    pub maximum_frame_rate: f64,
    pub maximum_dimension_pixels: u32,
    pub allowed_animated_properties: BTreeSet<String>,
    pub allowed_easing: BTreeSet<String>,
    pub allowed_network_modes: BTreeSet<MotionNetworkMode>,
}

impl Default for MotionPolicy {
    fn default() -> Self {
        Self {
            schema: MOTION_POLICY_SCHEMA.to_owned(),
            durations_ms: MotionDurationBudgets {
                micro_interaction: 200,
                transition: 500,
                landing_sequence: 2_000,
                continuous_status: 2_000,
                demo_capture: 15_000,
            },
            asset_bytes: MotionAssetBudgets {
                micro_interaction: 256 * 1024,
                transition: 512 * 1024,
                landing_sequence: 1024 * 1024,
                continuous_status: 512 * 1024,
                demo_capture: 4 * 1024 * 1024,
                static_imagery: 1024 * 1024,
            },
            maximum_frame_rate: 60.0,
            maximum_dimension_pixels: 3_840,
            allowed_animated_properties: BTreeSet::from([
                "opacity".to_owned(),
                "transform".to_owned(),
            ]),
            allowed_easing: BTreeSet::from([
                "ease-out".to_owned(),
                "ease-out-expo".to_owned(),
                "ease-out-quart".to_owned(),
                "ease-out-quint".to_owned(),
                "standard".to_owned(),
            ]),
            allowed_network_modes: BTreeSet::from([
                MotionNetworkMode::Offline,
                MotionNetworkMode::RecordedFixture,
            ]),
        }
    }
}

impl MotionPolicy {
    fn validate(&self) -> CompilerResult<()> {
        if self.schema != MOTION_POLICY_SCHEMA {
            return Err(motion_error(
                "motion-policy",
                format!("unsupported motion policy schema {:?}", self.schema),
                "Use identity.motion-policy/v1 before running motion quality checks.",
            ));
        }
        if !self.maximum_frame_rate.is_finite() || self.maximum_frame_rate <= 0.0 {
            return Err(motion_error(
                "maximumFrameRate",
                "motion policy frame-rate budget must be a positive finite number".to_owned(),
                "Set a positive finite maximum frame rate.",
            ));
        }
        if self.maximum_dimension_pixels == 0 {
            return Err(motion_error(
                "maximumDimensionPixels",
                "motion policy dimension budget must be greater than zero".to_owned(),
                "Set a positive maximum output dimension.",
            ));
        }
        if self.allowed_animated_properties.is_empty()
            || self.allowed_easing.is_empty()
            || self.allowed_network_modes.is_empty()
        {
            return Err(motion_error(
                "motion-policy",
                "motion policy allow-lists must not be empty".to_owned(),
                "Declare at least one allowed property, easing, and deterministic network mode.",
            ));
        }
        Ok(())
    }

    fn duration_budget(&self, purpose: MotionPurpose) -> Option<u64> {
        match purpose {
            MotionPurpose::MicroInteraction => Some(self.durations_ms.micro_interaction),
            MotionPurpose::Transition => Some(self.durations_ms.transition),
            MotionPurpose::LandingSequence => Some(self.durations_ms.landing_sequence),
            MotionPurpose::ContinuousStatus => Some(self.durations_ms.continuous_status),
            MotionPurpose::DemoCapture => Some(self.durations_ms.demo_capture),
            MotionPurpose::StaticImagery => None,
        }
    }

    fn byte_budget(&self, purpose: MotionPurpose) -> u64 {
        match purpose {
            MotionPurpose::MicroInteraction => self.asset_bytes.micro_interaction,
            MotionPurpose::Transition => self.asset_bytes.transition,
            MotionPurpose::LandingSequence => self.asset_bytes.landing_sequence,
            MotionPurpose::ContinuousStatus => self.asset_bytes.continuous_status,
            MotionPurpose::DemoCapture => self.asset_bytes.demo_capture,
            MotionPurpose::StaticImagery => self.asset_bytes.static_imagery,
        }
    }
}

